class Menu{"use strict";navbar=null;menu=null;menuButton=null;topLevelMenu=null;submenus=[];constructor(){this.navbar=document.getElementById("navbar"),this.menu=document.getElementById("mobile-menu"),this.menuButton=document.getElementById("mobile-menu-button"),this.topLevelItems=this.menu.querySelectorAll(".top-level-menu li a"),this.submenus=this.menu.querySelectorAll(".submenu"),this.menuButton.addEventListener("click",this.toggle.bind(this),!1),window.addEventListener("scroll",this.onScroll.bind(this),!1)}toggle(){this.menu.classList.contains("is-active")?this.hide():this.show()}show(){this.menu.classList.add("is-active"),document.getElementsByTagName("html")[0].classList.add("overflow-hidden","scrollbar-gutter-stable","bg-gray-50")}hide(){this.menu.classList.remove("is-active"),document.getElementsByTagName("html")[0].classList.remove("overflow-hidden","scrollbar-gutter-stable","bg-gray-50")}onScroll(){var e;window.matchMedia("(width >= 64rem)").matches||document.documentElement.scrollTop<10||((e=window.pageYOffset||document.documentElement.scrollTop)>this.lastScrollTop?this.navbar.classList.add("-top-24!"):this.navbar.classList.remove("-top-24!"),this.lastScrollTop=e)}openSubmenu(e,t){Number.isInteger(e)&&(t&&t.classList.add("is-active"),this.menu.dataset.submenu=!0,this.submenus[e].classList.add("translate-x-0!","shadow-2xl!"))}closeSubmenu(){delete this.menu.dataset.submenu,this.submenus.forEach(e=>e.classList.remove("translate-x-0!","shadow-2xl!")),setTimeout(()=>{this.topLevelItems.forEach(e=>e.classList.remove("is-active"))},100)}}